<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import type { DepositoDetraccionPayload,DetraccionProveedor,DetraccionProveedorFiltros,DetraccionProveedorLista,MovimientoDeposito } from '../interfaces/detraccion-proveedor.interface'
import { anularDepositoDetraccion,buscarMovimientosDetraccion,detalleDetraccionProveedor,listarDetraccionesProveedor,registrarDepositoDetraccion } from '../services/detraccion-proveedor'
const blankFilters=():DetraccionProveedorFiltros=>({proveedor:'',estado:'',fecha_desde:'',fecha_hasta:''}),blankDeposit=():DepositoDetraccionPayload=>({movimiento_id:0,fecha_deposito:new Date().toISOString().slice(0,10),numero_constancia:'',numero_operacion:''})
const filters=reactive(blankFilters()),deposit=reactive(blankDeposit()),rows=ref<DetraccionProveedorLista[]>([]),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),detail=ref<DetraccionProveedor|null>(null),showDeposit=ref(false),movementQuery=ref(''),movements=ref<MovimientoDeposito[]>([]),selectedMovement=ref<MovimientoDeposito|null>(null)
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0)),date=(v?:string)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'-'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarDetraccionesProveedor(filters,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function view(item:DetraccionProveedorLista){loading.value=true;try{detail.value=await detalleDetraccionProveedor(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function openDeposit(item:DetraccionProveedorLista){loading.value=true;try{detail.value=await detalleDetraccionProveedor(item.id);Object.assign(deposit,blankDeposit());movementQuery.value='';selectedMovement.value=null;movements.value=[];showDeposit.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function searchMovements(){if(movementQuery.value.length<3)return;try{movements.value=await buscarMovimientosDetraccion(movementQuery.value)}catch(e){error.value=message(e)}}
function selectMovement(item:MovimientoDeposito){selectedMovement.value=item;deposit.movimiento_id=item.id;movementQuery.value=item.text||`${item.numero_comprobante_texto} - ${item.glosa}`;movements.value=[]}
async function saveDeposit(){if(!detail.value)return;loading.value=true;error.value='';try{await registrarDepositoDetraccion(detail.value.id,{...deposit});success.value='Depósito registrado correctamente.';showDeposit.value=false;detail.value=null;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function cancelDeposit(item:DetraccionProveedorLista){const id=item.pago_activo?.id;if(!id||!confirm('¿Desea anular el depósito y devolver la detracción a pendiente?'))return;loading.value=true;try{await anularDepositoDetraccion(id);success.value='Depósito anulado correctamente.';await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,blankFilters());load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Gestión de detracciones</nav><header class="hero"><div class="mark">DT</div><div><small>MIA · FINANZAS · PROVEEDORES</small><h1>Gestión de detracciones</h1><p>Control de obligaciones y depósitos asociados a documentos de proveedores.</p></div><strong>{{total}} detracciones</strong></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="filters.proveedor" placeholder="RUC o razón social"><select v-model="filters.estado"><option value="">Todos los estados</option><option>PENDIENTE</option><option>DEPOSITADA</option></select><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron detracciones.</div><div v-else class="scroll"><table><thead><tr><th>Documento</th><th>Proveedor</th><th>Bien o servicio</th><th>Base</th><th>Porcentaje</th><th>Detracción</th><th>Estado</th><th>Depósito</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.documento_proveedor.numero_documento_completo}}</b><small>{{date(item.documento_proveedor.fecha_emision)}}</small></td><td><b>{{item.documento_proveedor.proveedor_numero_documento}}</b><small>{{item.documento_proveedor.proveedor_razon_social}}</small></td><td><b>{{item.codigo_bien_servicio}}</b><small>{{item.descripcion_bien_servicio}}</small></td><td class="number">{{money(item.base_calculo)}}</td><td class="number">{{Number(item.porcentaje).toFixed(2)}}%</td><td class="number"><b>{{money(item.importe_detraccion)}}</b></td><td><span :class="item.estado==='DEPOSITADA'?'good':'warn'">{{item.estado}}</span></td><td><template v-if="item.pago_activo"><b>{{item.pago_activo.numero_constancia}}</b><small>{{item.pago_activo.fecha_deposito}}</small></template><span v-else>-</span></td><td class="actions"><button @click="view(item)">Ver</button><button v-if="item.estado==='PENDIENTE'" class="deposit" @click="openDeposit(item)">Registrar depósito</button><button v-if="item.pago_activo" class="danger" @click="cancelDeposit(item)">Anular depósito</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="detail&&!showDeposit" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>DETRACCIÓN #{{detail.id}}</small><h2>{{detail.documento.numero}}</h2></div><span :class="detail.detraccion.estado==='DEPOSITADA'?'good':'warn'">{{detail.detraccion.estado}}</span><button @click="detail=null">×</button></header><div class="facts"><div><small>PROVEEDOR</small><b>{{detail.proveedor.ruc}} · {{detail.proveedor.razon_social}}</b></div><div><small>DOCUMENTO</small><b>{{detail.documento.tipo}} · {{detail.documento.fecha}}</b></div><div><small>IMPORTE DOCUMENTO</small><b>{{money(detail.documento.importe)}}</b></div><div><small>IMPORTE DETRACCIÓN</small><b>{{money(detail.detraccion.importe)}}</b></div></div><h3>{{detail.detraccion.codigo}} · {{detail.detraccion.descripcion}}</h3><p>Base de cálculo: {{money(detail.detraccion.base_calculo)}} · Porcentaje: {{detail.detraccion.porcentaje}}%</p><section v-if="detail.pago_activo" class="payment"><small>DEPÓSITO ACTIVO</small><b>Constancia {{detail.pago_activo.numero_constancia}}</b><span>Fecha {{detail.pago_activo.fecha_deposito}} · Operación {{detail.pago_activo.numero_operacion||'-'}}</span></section></section></div>
<div v-if="showDeposit&&detail" class="backdrop" @mousedown.self="showDeposit=false"><form class="dialog" @submit.prevent="saveDeposit"><header><div><small>REGISTRAR DEPÓSITO</small><h2>{{detail.documento.numero}}</h2><p>{{detail.proveedor.ruc}} · {{detail.proveedor.razon_social}} · {{money(detail.detraccion.importe)}}</p></div><button type="button" @click="showDeposit=false">×</button></header><div class="movement"><label>Movimiento financiero de egreso<input v-model.trim="movementQuery" required placeholder="Comprobante, documento o glosa" @input="searchMovements"></label><ul v-if="movements.length"><li v-for="x in movements" :key="x.id" @click="selectMovement(x)"><b>{{x.numero_comprobante_texto}}</b> {{x.fecha}} · {{x.glosa}} <strong>{{money(x.total_egreso)}}</strong></li></ul></div><div class="grid"><label>Fecha de depósito<input v-model="deposit.fecha_deposito" type="date" required></label><label>Número de constancia<input v-model.trim="deposit.numero_constancia" maxlength="50" required></label><label>Número de operación<input v-model.trim="deposit.numero_operacion" maxlength="50"></label><label>Importe a depositar<input :value="money(detail.detraccion.importe)" readonly></label></div><p class="notice">El importe se obtiene de la detracción y no puede modificarse desde esta pantalla.</p><footer><button type="button" class="soft" @click="showDeposit=false">Cancelar</button><button :disabled="loading||!deposit.movimiento_id">Registrar depósito</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small,.facts small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto auto;gap:7px;background:#fff}.filters label{display:flex;align-items:center;gap:5px;font-size:.5rem}.filters input,.filters select,.dialog input{box-sizing:border-box;width:100%;padding:8px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.5rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse;font-size:.48rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.number{text-align:right}.good,.warn{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.44rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.warn{color:#886113;background:#fff2d3}.actions{display:flex;gap:4px}.deposit{background:#27875f}.danger{background:#b74b54}.empty{padding:55px;text-align:center}.card>footer,.dialog>footer{padding:12px;display:flex;justify-content:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(800px,100%);max-height:92vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;gap:10px}.dialog>header div{flex:1}.dialog h2{margin:3px 0}.dialog header p{font-size:.5rem}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.facts{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:8px;margin-top:12px}.facts div{display:grid;gap:4px;padding:10px;background:#f1f6f7}.dialog h3{font-size:.65rem}.dialog p,.payment{font-size:.53rem}.payment{display:grid;gap:5px;padding:12px;background:#eaf7ef}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.grid label,.movement label{display:grid;gap:4px;color:#5d7078;font-size:.5rem;font-weight:700}.movement{position:relative;margin-bottom:10px}.movement ul{position:absolute;z-index:3;width:100%;margin:2px 0;padding:0;border:1px solid #ddd;background:#fff;list-style:none}.movement li{padding:8px;font-size:.48rem;cursor:pointer}.movement li strong{float:right}.notice{padding:9px;color:#795c1c;background:#fff5d9}@media(max-width:750px){.filters,.grid,.facts{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero .mark{display:none}}
</style>
